import java.util.*;

public class Main {
    // Is there a repeat of length len whose two copies do not overlap? Returns a start or -1.
    static int find(Integer[] sa, int[] lcp, int len) {
        int mn = 0, mx = 0;
        for (int r = 0; r < sa.length; r++) {
            // Ranks joined by lcp >= len form one block: they all share the same first len letters.
            if (r > 0 && lcp[r] >= len) { mn = Math.min(mn, sa[r]); mx = Math.max(mx, sa[r]); }
            else { mn = sa[r]; mx = sa[r]; }
            if (mx - mn >= len) return mn;       // far enough apart: no overlap
        }
        return -1;
    }

    static void solve(String s) {
        int n = s.length();
        Integer[] sa = new Integer[n];
        for (int i = 0; i < n; i++) sa[i] = i;
        Arrays.sort(sa, (a, b) -> s.substring(a).compareTo(s.substring(b)));
        int[] lcp = new int[n];                  // lcp[r]: letters shared by sorted suffixes r-1 and r
        for (int r = 1; r < n; r++) {
            int a = sa[r - 1], b = sa[r], h = 0;
            while (a + h < n && b + h < n && s.charAt(a + h) == s.charAt(b + h)) h++;
            lcp[r] = h;
        }
        int best = 0, at = 0;                    // overlap allowed: the largest lcp value
        for (int r = 1; r < n; r++) if (lcp[r] > best) { best = lcp[r]; at = sa[r]; }
        int lo = 0, hi = n / 2, start = 0;       // no overlap: binary search on the length
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2, f = find(sa, lcp, mid);
            if (f >= 0) { lo = mid; start = f; } else hi = mid - 1;
        }
        System.out.println(s + ": overlap allowed = \"" + s.substring(at, at + best) + "\" (" + best
            + "), no overlap = \"" + s.substring(start, start + lo) + "\" (" + lo + ")");
    }

    public static void main(String[] args) {
        solve("banana");
        solve("aaaa");
        // With a fast suffix array: O(N log N) time, O(N) space. This demo sorts naively.
    }
}

